class Solution:
    def checkValidString(self, s: str) -> bool:
        # [lower, upper] -> Upper and lower bound of possible open brackets. By the end is 0 in our possibilities?
        bound = [0, 0]
        for c in s:

            if c == "(":
                bound[0] += 1
                bound[1] += 1
            elif c == ")":
                bound[0] -= 1
                bound[1] -= 1
            else:
                bound[0] -= 1
                bound[1] += 1

            if not bound[1] >= 0:
               return False

        return True if (bound[0] <= 0 and bound[1] >= 0) else False

