class Solution:
    def checkValidString(self, s: str) -> bool:

        @cache
        def dfs(open, i):
            #IMPORTANT
            if open < 0:
                return False

            if i == len(s):
                return True if open == 0 else False

            if s[i] == "(":
                return dfs(open + 1, i+1)
            elif s[i] == ")":
                return dfs(open - 1, i+1)
            else:
                if dfs(open - 1, i+1):
                    return True
                if dfs(open + 1, i+1):
                    return True
                if dfs(open, i+1):
                    return True
            return False

        return dfs(0, 0)

